SELECT ta.project_id, cp.serial_number AS project_serial_number, cp.short_name AS project_short_name, ta.monomer_id, pm.name AS monomer_name, ta.area_id, pa.name AS area_name, ta.id AS product_id, ta.name AS product_name, ta.serial_number AS product_serial_number, ta.specification AS product_specification, ta.length AS product_length, ta.material AS product_material, ta.quantity, ta.net_weight AS product_net_weight, (ta.quantity * ta.net_weight) AS product_total_net_weight, ta.create_time AS import_date FROM tech_artifact ta LEFT JOIN contract_project cp ON cp.bool_delete_enum = FALSE AND cp.id = ta.project_id LEFT JOIN plan_monomer pm ON pm.bool_delete_enum = FALSE AND pm.id = ta.monomer_id LEFT JOIN plan_area pa ON pa.bool_delete_enum = FALSE AND pa.id = ta.area_id WHERE ta.bool_delete_enum = FALSE AND ta.project_id = #{projectId}
AND ta.monomer_id = #{monomerId}
AND ta.area_id = #{areaId}

SELECT t.project_id, cp.serial_number AS project_serial_number, cp.short_name AS project_short_name, t.monomer_id, pm.name AS monomer_name, t.area_id, pa.name AS area_name, ta.id AS product_id, ta.name AS product_name, ta.serial_number AS product_serial_number, ta.specification AS product_specification, ta.length AS product_length, ta.material AS product_material, IFNULL(t.quantity, 0) AS quantity, ta.net_weight AS product_net_weight, IFNULL(t.quantity * ta.net_weight, 0) AS product_total_net_weight, t.import_date FROM ( SELECT mbt.project_id, mbt.monomer_id, mbt.area_id, mbt.product_id, SUM(mbt.task_quantity) AS quantity, mbt.in_year_month_day_date AS import_date FROM mes_building_task mbt WHERE mbt.bool_delete_enum = FALSE AND mbt.task_type_enum = 2 AND mbt.project_id = #{projectId}
AND mbt.monomer_id = #{monomerId}
AND mbt.area_id = #{areaId}
GROUP BY mbt.project_id, mbt.monomer_id, mbt.area_id, mbt.product_id,mbt.in_year_month_day_date ) t LEFT JOIN tech_artifact ta ON ta.bool_delete_enum = FALSE AND ta.id = t.product_id LEFT JOIN contract_project cp ON cp.bool_delete_enum = FALSE AND cp.id = t.project_id LEFT JOIN plan_monomer pm ON pm.bool_delete_enum = FALSE AND pm.id = t.monomer_id LEFT JOIN plan_area pa ON pa.bool_delete_enum = FALSE AND pa.id = t.area_id

SELECT t.project_id, cp.serial_number AS project_serial_number, cp.short_name AS project_short_name, t.monomer_id, pm.name AS monomer_name, t.area_id, pa.name AS area_name, ta.id AS product_id, ta.name AS product_name, ta.serial_number AS product_serial_number, ta.specification AS product_specification, ta.length AS product_length, ta.material AS product_material, IFNULL(t.quantity, 0) AS quantity, ta.net_weight AS product_net_weight, IFNULL(t.quantity * ta.net_weight, 0) AS product_total_net_weight, t.import_date FROM ( SELECT mbt.project_id, mbt.monomer_id, mbt.area_id, mbt.product_id, SUM(mbt.quantity) AS quantity, mbt.in_year_month_day_date AS import_date FROM mes_building_complete mbt WHERE mbt.bool_delete_enum = FALSE AND mbt.task_type_enum = 2 AND mbt.project_id = #{projectId}
AND mbt.monomer_id = #{monomerId}
AND mbt.area_id = #{areaId}
GROUP BY mbt.project_id, mbt.monomer_id, mbt.area_id, mbt.product_id,mbt.in_year_month_day_date ) t LEFT JOIN tech_artifact ta ON ta.bool_delete_enum = FALSE AND ta.id = t.product_id LEFT JOIN contract_project cp ON cp.bool_delete_enum = FALSE AND cp.id = t.project_id LEFT JOIN plan_monomer pm ON pm.bool_delete_enum = FALSE AND pm.id = t.monomer_id LEFT JOIN plan_area pa ON pa.bool_delete_enum = FALSE AND pa.id = t.area_id

SELECT ta.project_id, cp.serial_number AS project_serial_number, cp.short_name AS project_short_name, ta.monomer_id, pm.name AS monomer_name, ta.area_id, pa.name AS area_name, ta.id AS product_id, ta.name AS product_name, ta.serial_number AS product_serial_number, ta.specification AS product_specification, ta.length AS product_length, ta.material AS product_material, IFNULL((ta.quantity - ta.produced_quantity), 0) AS quantity, ta.net_weight AS product_net_weight, IFNULL((ta.quantity - ta.produced_quantity) * ta.net_weight, 0) AS product_total_net_weight, ta.create_time AS import_date FROM tech_artifact ta LEFT JOIN contract_project cp ON cp.bool_delete_enum = FALSE AND cp.id = ta.project_id LEFT JOIN plan_monomer pm ON pm.bool_delete_enum = FALSE AND pm.id = ta.monomer_id LEFT JOIN plan_area pa ON pa.bool_delete_enum = FALSE AND pa.id = ta.area_id WHERE ta.bool_delete_enum = FALSE AND ta.quantity > ta.produced_quantity AND ta.project_id = #{projectId}
AND ta.monomer_id = #{monomerId}
AND ta.area_id = #{areaId}

SELECT t.project_id, cp.serial_number AS project_serial_number, cp.short_name AS project_short_name, t.monomer_id, pm.name AS monomer_name, t.area_id, pa.name AS area_name, ta.id AS product_id, ta.name AS product_name, ta.serial_number AS product_serial_number, ta.specification AS product_specification, ta.length AS product_length, ta.material AS product_material, IFNULL(t.quantity, 0) AS quantity, ta.net_weight AS product_net_weight, IFNULL(t.quantity * ta.net_weight, 0) AS product_total_net_weight, t.import_date FROM ( SELECT mbws.project_id, mbws.monomer_id, mbws.area_id, mbws.product_id, sum(mbws.quantity) AS quantity, mbws.in_year_month_day_date AS import_date FROM mes_building_warehouse_record mbws WHERE mbws.bool_delete_enum = FALSE AND mbws.type = 2 AND mbws.product_type = 2 AND mbws.project_id = #{projectId}
AND mbws.monomer_id = #{monomerId}
AND mbws.area_id = #{areaId}
GROUP BY mbws.project_id, mbws.monomer_id, mbws.area_id, mbws.product_id,mbws.in_year_month_day_date ) t LEFT JOIN tech_artifact ta ON ta.bool_delete_enum = FALSE AND ta.id = t.product_id LEFT JOIN contract_project cp ON cp.bool_delete_enum = FALSE AND cp.id = t.project_id LEFT JOIN plan_monomer pm ON pm.bool_delete_enum = FALSE AND pm.id = t.monomer_id LEFT JOIN plan_area pa ON pa.bool_delete_enum = FALSE AND pa.id = t.area_id
